create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.fails(statement text,expected text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception 'Unexpected success: %',label;end $$;
update private.memory_publication_settings set writes_enabled=true,images_enabled=true,asset_limit=20,asset_bytes_limit=100000000;
update private.memory_eligibility_evidence set state='GRANTED',expires_at=clock_timestamp()+interval '1 hour' where purpose='PUBLIC_PUBLISH';
update public.memory_cards set status='COMPLETE_PRIVATE' where id='77777777-7777-4777-8777-777777777950';
insert into private.memory_public_image_rights(user_id,asset_id,source_version,image_type,evidence_ref) values('77777777-7777-4777-8777-777777777777','77777777-7777-4777-8777-777777777952',1,'USER_ORIGINAL','SYNTHETIC_LOCAL_ONLY');
select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',false);
set role authenticated;
select set_config('test.public.asset',public.reserve_memory_public_asset('77777777-7777-4777-8777-777777777952',1,'44444444-4444-4444-8444-444444444441','ELIGIBILITY_LOCAL_PUBLIC')->>'id',false);
reset role;
update private.memory_eligibility_evidence set state='REVOKED' where purpose='PUBLIC_PUBLISH';
set role service_role;
select pg_temp.fails($q$select public.complete_memory_public_asset(current_setting('test.public.asset')::uuid,repeat('a',64),repeat('b',64),100,100,10,10)$q$,'ELIGIBILITY_REQUIRED','public completion uses stored owner eligibility');
reset role;
select pg_temp.ok((select state='PREPARING' and reserved_bytes=4194304 from private.memory_public_assets where id=current_setting('test.public.asset')::uuid),'denied public completion preserves reserved quota');
set role authenticated;
select public.cancel_memory_public_asset(current_setting('test.public.asset')::uuid);
reset role;
select pg_temp.ok((select state='CANCELLED' and reserved_bytes=4194304 from private.memory_public_assets where id=current_setting('test.public.asset')::uuid),'revoked owner can cancel without premature quota release');
update private.memory_eligibility_evidence set state='GRANTED',expires_at=clock_timestamp()+interval '1 hour' where purpose='PUBLIC_PUBLISH';
set role authenticated;
select set_config('test.public.asset',public.reserve_memory_public_asset('77777777-7777-4777-8777-777777777952',1,'44444444-4444-4444-8444-444444444442','ELIGIBILITY_LOCAL_PUBLIC')->>'id',false);
reset role;
update private.memory_public_image_rights set revoked_at=now() where user_id='77777777-7777-4777-8777-777777777777';
set role service_role;
select pg_temp.fails($q$select public.complete_memory_public_asset(current_setting('test.public.asset')::uuid,repeat('a',64),repeat('b',64),100,100,10,10)$q$,'PUBLICATION_RESTRICTED','eligibility never replaces separate image rights');
select pg_temp.fails($q$select private.complete_public_asset_before_eligibility(current_setting('test.public.asset')::uuid,repeat('a',64),repeat('b',64),100,100,10,10)$q$,'permission denied','service cannot bypass public completion eligibility');
reset role;
update private.memory_public_image_rights set revoked_at=null where user_id='77777777-7777-4777-8777-777777777777';
set role service_role;
select public.complete_memory_public_asset(current_setting('test.public.asset')::uuid,repeat('a',64),repeat('b',64),100,100,10,10);
reset role;
select pg_temp.ok((select state='READY' and reserved_bytes=200 from private.memory_public_assets where id=current_setting('test.public.asset')::uuid),'eligible public completion retains measured byte settlement');
